<?php defined('BASEPATH') or exit('No direct script access allowed');
class M_saldo_siswa extends CI_Model
{
    public function result($f){$this->query($f,true);$total=(int)$this->db->count_all_results();$this->query($f,false);$rows=$this->db->limit($f['limit'],($f['page']-1)*$f['limit'])->get()->result_array();return ['rows'=>$rows,'meta'=>['page'=>$f['page'],'limit'=>$f['limit'],'total'=>$total,'pages'=>max(1,(int)ceil($total/$f['limit']))]];}
    private function query($f,$count){$this->db->select($count?'sd.id':"sd.id,sd.id_siswa,sd.nis,sd.nama_siswa,sd.saldo,sd.status_dompet,sd.alasan_blokir,k.nama_kelas,pds.batas_harian,pds.batas_per_transaksi,pds.status_aktif status_limit,pd.batas_harian_default,pd.batas_transaksi_default",false)->from('saldo_dompet_siswa sd')->join('siswa s','s.id=sd.id_siswa')->join('kelas_siswa ks',"ks.id=(SELECT MAX(k2.id) FROM kelas_siswa k2 JOIN kelas_setting st2 ON st2.id=k2.id_kelas_setting JOIN master_tahun_ajaran ta2 ON ta2.id=st2.id_periode AND ta2.status='Aktif' WHERE k2.id_siswa=s.id AND k2.status_aktif IN ('1','AKTIF'))",'left',false)->join('kelas_setting k','k.id=ks.id_kelas_setting','left')->join('pengaturan_dompet_siswa pds','pds.id_siswa=s.id','left')->join('(SELECT * FROM pengaturan_dompet ORDER BY id DESC LIMIT 1) pd','1=1','left',false);if($f['search']!=='')$this->db->group_start()->like('sd.nis',$f['search'])->or_like('sd.nama_siswa',$f['search'])->group_end();if(in_array($f['status'],['AKTIF','NONAKTIF'],true))$this->db->where('sd.status_dompet',$f['status']);if(!$count)$this->db->order_by('sd.nama_siswa');}
    public function history($id,$limit=50)
    {
        $id=(int)$id;$limit=max(1,min(50,(int)$limit));
        $wallet=$this->db->select('sd.*,s.nama_lengkap')->from('saldo_dompet_siswa sd')->join('siswa s','s.id=sd.id_siswa','left')->where('sd.id_siswa',$id)->get()->row_array();
        $sql="SELECT id sort_id,'ISI_SALDO' jenis,no_transaksi,nominal_saldo nominal,saldo_sebelum,saldo_sesudah,status_transaksi status,sumber_transaksi sumber,COALESCE(keterangan,'') keterangan,tanggal,waktu FROM riwayat_isi_saldo WHERE id_siswa=? UNION ALL SELECT id sort_id,'TRANSAKSI_KANTIN' jenis,no_transaksi,nominal,saldo_sebelum,saldo_sesudah,status_transaksi status,sumber_transaksi sumber,COALESCE(keterangan,'') keterangan,tanggal,waktu FROM transaksi_kantin WHERE id_siswa=? ORDER BY tanggal DESC,waktu DESC,sort_id DESC LIMIT {$limit}";
        $entries=$this->db->query($sql,[$id,$id])->result_array();
        $summary=['total'=>count($entries),'topup_count'=>0,'topup_nominal'=>0,'kantin_count'=>0,'kantin_nominal'=>0];
        foreach($entries as $entry){if($entry['jenis']==='ISI_SALDO'){$summary['topup_count']++;$summary['topup_nominal']+=(int)$entry['nominal'];}else{$summary['kantin_count']++;$summary['kantin_nominal']+=(int)$entry['nominal'];}}
        return ['wallet'=>$wallet,'entries'=>$entries,'summary'=>$summary,'topup'=>array_values(array_filter($entries,static function($row){return $row['jenis']==='ISI_SALDO';})),'kantin'=>array_values(array_filter($entries,static function($row){return $row['jenis']==='TRANSAKSI_KANTIN';}))];
    }
    public function set_limit($id,$harian,$transaksi,$user){if(!$this->db->where('id_siswa',$id)->count_all_results('saldo_dompet_siswa'))return $this->err('Wallet siswa tidak ditemukan.',404);$data=['batas_harian'=>$harian,'batas_per_transaksi'=>$transaksi,'status_aktif'=>'AKTIF','tanggal_update'=>date('Y-m-d'),'waktu_update'=>date('H:i:s'),'id_user_update'=>(int)$user['id'],'nama_user_update'=>$user['nama_user'],'sumber_perubahan'=>'WEB'];$old=$this->db->get_where('pengaturan_dompet_siswa',['id_siswa'=>$id])->row_array();$ok=$old?$this->db->where('id_siswa',$id)->update('pengaturan_dompet_siswa',$data):$this->db->insert('pengaturan_dompet_siswa',array_merge($data,['id_siswa'=>$id]));return $ok?['success'=>true]:$this->err('Limit gagal diperbarui.',500);}
    public function set_status($id,$status,$reason,$user){$this->db->trans_begin();$wallet=$this->db->query('SELECT id FROM saldo_dompet_siswa WHERE id_siswa=? FOR UPDATE',[$id])->row_array();if(!$wallet){$this->db->trans_rollback();return $this->err('Wallet siswa tidak ditemukan.',404);}$this->db->where('id_siswa',$id)->update('saldo_dompet_siswa',['status_dompet'=>$status,'alasan_blokir'=>$status==='AKTIF'?null:$reason,'tanggal_update'=>date('Y-m-d'),'waktu_update'=>date('H:i:s'),'id_user_update'=>(int)$user['id'],'nama_user_update'=>$user['nama_user']]);$this->db->insert('log_aktivitas_dompet',['id_user'=>(int)$user['id'],'nama_user'=>$user['nama_user'],'level'=>$user['level'],'modul'=>'SALDO_SISWA','aksi'=>$status==='AKTIF'?'AKTIFKAN_LAYANAN':'BLOKIR_LAYANAN','id_referensi'=>$id,'keterangan'=>$reason,'alamat_ip'=>$this->input->ip_address(),'tanggal'=>date('Y-m-d'),'waktu'=>date('H:i:s')]);if($this->db->trans_status()===false){$this->db->trans_rollback();return $this->err('Status layanan gagal diperbarui.',500);}$this->db->trans_commit();return ['success'=>true];}
    private function err($m,$s){return ['success'=>false,'message'=>$m,'status'=>$s];}
}
